IF DB_ID('LP1_StartupFunding') IS NULL
    CREATE DATABASE LP1_StartupFunding;
GO
USE LP1_StartupFunding;
GO

IF OBJECT_ID('dbo.startup_funding', 'U') IS NOT NULL DROP TABLE dbo.startup_funding;
CREATE TABLE dbo.startup_funding
(
    funding_id          INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    funding_year        SMALLINT          NOT NULL,
    company_name        NVARCHAR(200)     NULL,
    founded_year        SMALLINT          NULL,
    headquarters_city   NVARCHAR(100)     NULL,
    headquarters_state  NVARCHAR(100)     NULL,
    industry            NVARCHAR(300)     NULL,
    about_company       NVARCHAR(1000)    NULL,
    founders            NVARCHAR(500)     NULL,
    investor            NVARCHAR(500)     NULL,
    amount_usd          BIGINT            NULL,
    funding_round       NVARCHAR(100)     NULL,
    loaded_at           DATETIME2         NOT NULL CONSTRAINT DF_startup_funding_loaded DEFAULT SYSUTCDATETIME()
);
GO

