-- Indexes for common analytical queries
CREATE INDEX IX_sf_year    ON dbo.startup_funding (funding_year) INCLUDE (amount_usd);
CREATE INDEX IX_sf_city    ON dbo.startup_funding (headquarters_city);
CREATE INDEX IX_sf_industry ON dbo.startup_funding (industry);
GO

-- ============ ANALYTICAL VIEWS ============

-- Headline yearly funding trend (total, deal count, average, median)
CREATE OR ALTER VIEW dbo.v_yearly_funding_trend AS
SELECT funding_year,
       COUNT(*)                              AS deal_count,
       SUM(amount_usd)                       AS total_funding_usd,
       AVG(CAST(amount_usd AS FLOAT))        AS avg_deal_usd,
       PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY amount_usd)
                                 AS median_deal_usd
FROM dbo.startup_funding
GROUP BY funding_year;
GO

-- Year-over-year change on total funding
CREATE OR ALTER VIEW dbo.v_yoy_change AS
SELECT funding_year,
       total_funding_usd,
       LAG(total_funding_usd) OVER (ORDER BY funding_year) AS prev_year_usd,
       total_funding_usd - LAG(total_funding_usd) OVER (ORDER BY funding_year) AS yoy_diff_usd,
       ROUND(100.0 * (total_funding_usd - LAG(total_funding_usd) OVER (ORDER BY funding_year))
             / NULLIF(LAG(total_funding_usd) OVER (ORDER BY funding_year), 0), 1) AS yoy_pct
FROM dbo.v_yearly_funding_trend;
GO

-- Funding by industry and year
CREATE OR ALTER VIEW dbo.v_industry_funding AS
SELECT industry, funding_year,
       COUNT(*)                       AS deal_count,
       SUM(amount_usd)                AS total_funding_usd,
       AVG(CAST(amount_usd AS FLOAT)) AS avg_deal_usd
FROM dbo.startup_funding
WHERE industry IS NOT NULL
GROUP BY industry, funding_year;
GO

-- Funding by headquarters city and year
CREATE OR ALTER VIEW dbo.v_location_funding AS
SELECT headquarters_city, headquarters_state, funding_year,
       COUNT(*)        AS deal_count,
       SUM(amount_usd) AS total_funding_usd
FROM dbo.startup_funding
WHERE headquarters_city IS NOT NULL
GROUP BY headquarters_city, headquarters_state, funding_year;
GO

-- Funding round mix per year
CREATE OR ALTER VIEW dbo.v_round_mix AS
SELECT funding_round, funding_year,
       COUNT(*)        AS deal_count,
       SUM(amount_usd) AS total_funding_usd
FROM dbo.startup_funding
WHERE funding_round IS NOT NULL
GROUP BY funding_round, funding_year;
GO

-- Top investors by total deployed capital
CREATE OR ALTER VIEW dbo.v_top_investors AS
SELECT TOP 50 investor,
       COUNT(*)        AS deal_count,
       SUM(amount_usd) AS total_funding_usd
FROM dbo.startup_funding
WHERE investor IS NOT NULL
GROUP BY investor
ORDER BY total_funding_usd DESC;
GO

-- Verification query
SELECT funding_year, COUNT(*) AS rows_loaded, SUM(amount_usd) AS total_usd
FROM dbo.startup_funding GROUP BY funding_year ORDER BY funding_year;
GO